use Illuminate\Database\Eloquent\Relations\BelongsToMany;

public function products(): BelongsToMany
{
    return $this->belongsToMany(Product::class)
        ->withPivot('quantity', 'price')
        ->withTimestamps();
}

$order = Order::find(1);

// products jodo (pivot ke extra data ke saath)
$order->products()->attach(5, ['quantity' => 2, 'price' => 799]);
$order->products()->attach([
    6 => ['quantity' => 1, 'price' => 1499],
    7 => ['quantity' => 3, 'price' => 150],
]);

$order->products()->detach(7);          // ek hatao
$order->products()->detach();           // saare hatao

$order->products()->sync([5, 6]);       // bas yahi do rahein, baaki hat jaayein
$order->products()->syncWithoutDetaching([8]);  // jodo, hatao mat
$order->products()->toggle([5, 9]);     // jo hai wo hatao, jo nahi wo jodo
